from typing import Tuple, List
from collections import defaultdict

def solve_math_problem(roots: Tuple[int, ...], power: int, target_sum_indices: int) -> int:
    """
    Calculates the sum of coefficients a_k for even k in the polynomial
    product_{i=1}^n (x + r_i)^p.
    """
    # Polynomial representation as a dictionary {exponent: coefficient}
    # Start with (x + 0)^0 = 1
    poly = {0: 1}

    for root in roots:
        # Multiply current poly by (x + root)^power
        # (x + root)^power = sum_{j=0}^power binom(power, j) * root^(power-j) * x^j
        factor_poly = {}
        for j in range(power + 1):
            comb = 1
            for i in range(j):
                comb = comb * (power - i) // (i + 1)
            coeff = comb * (root ** (power - j))
            factor_poly[j] = coeff

        new_poly = defaultdict(int)
        for exp1, coeff1 in poly.items():
            for exp2, coeff2 in factor_poly.items():
                new_poly[exp1 + exp2] += coeff1 * coeff2
        poly = dict(new_poly)

    total_sum = 0
    for k in range(2, target_sum_indices + 1, 2):
        total_sum += poly.get(k, 0)

    return total_sum

