        if abs(a - 1.0) < 1e-9:
            b = b_n / n
        else:
            b = b_n * (a - 1) / (a_n - 1)

        return float(a + b)
    except (ZeroDivisionError, ValueError, TypeError) as e:
        raise ValueError("Invalid input parameters for the given math problem.") from e

