from typing import List, Optional, Set

def solve_math_problem(n: int) -> Optional[int]:
    def is_square(num: int) -> bool:
        root = int(num**0.5)
        return root * root == num

    adj = {i: [] for i in range(1, n + 1)}
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if i != j and is_square(i + j):
                adj[i].append(j)

    def backtrack(current_path: List[int], visited: Set[int]) -> Optional[List[int]]:
