```python
from typing import List, Optional, Set

def solve_math_problem(n: int) -> Optional[int]:
    def is_square(num: int) -> bool:
        root = int(num**0.5)
        return root * root == num

    adj = {i: [] for i in range(1, n + 1)}
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if i != j and is_square(i + j):
                adj[i].append(j)

    def backtrack(current_path: List[int], visited: Set[int]) -> Optional[List[int]]:
        if len(current_path) == n:
            if is_square(current_path[0] + current_path[-1]):
                return current_path
            return None

        last = current_path[-1]
        for neighbor in adj[last]:
            if neighbor not in visited:
                visited.add(neighbor)
                current_path.append(neighbor)
                result = backtrack(current_path, visited)
                if result:
                    return result
                current_path.pop()
                visited.remove(neighbor)
        return None

    for start_node in range(1, n + 1):
        path = backtrack([start_node], {start_node})
        if path:
            return path[0] + path[-1]

    return None
